def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'

    opp = [h[1] for h in history]
    mine = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = mine[-1]

    total_opp_c = opp.count('C')
    opp_rate = total_opp_c / n

    window = min(12, n)
    recent = opp[-window:]
    recent_c = recent.count('C')
    recent_rate = recent_c / window

    tail_opp_def = 0
    for a in reversed(opp):
        if a == 'D':
            tail_opp_def += 1
        else:
            break

    tail_opp_c = 0
    for a in reversed(opp):
        if a == 'C':
            tail_opp_c += 1
        else:
            break

    tail_cc = 0
    for i in range(n - 1, -1, -1):
        if mine[i] == 'C' and opp[i] == 'C':
            tail_cc += 1
        else:
            break

    remaining = 100 - n

    # Endgame exploitation when opponent is clearly cooperative.
    if remaining <= 2:
        if opp_rate > 0.6:
            return 'D'
        if remaining <= 2 and recent_rate > 0.7:
            return 'D'

    if n >= 95:
        if opp_rate > 0.55:
            return 'D'
        if last_opp == 'C' and recent_rate >= 0.6:
            return 'D'

    # Long mutual cooperation: keep it, with rare late probes near end.
    if tail_cc >= 12:
        if remaining <= 6 and n >= 90:
            return 'D'
        return 'C'

    # Very cooperative opponent overall: cooperate, exploit late.
    if opp_rate > 0.9 and total_opp_c >= n - 1:
        if remaining <= 20 and n >= 80:
            return 'D'
        return 'C'

    # Extremely defective opponent: minimize losses.
    if opp_rate < 0.25 and n >= 8:
        return 'D'

    # Respond to recent defection.
    if last_opp == 'D':
        if tail_opp_def >= 3:
            return 'D'
        if recent_rate < 0.35:
            return 'D'
        # A single defection in an otherwise cooperative match: retaliate once,
        # then return to cooperation.
        if tail_opp_def == 1 and recent_rate >= 0.6:
            if last_me == 'C':
                return 'D'
            return 'C'
        if tail_opp_def == 1 and rng.random() < 0.5:
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if recent_rate >= 0.55:
        # We defected unprovoked; try to stabilize back to cooperation.
        if last_me == 'D':
            if tail_cc >= 1:
                return 'C'
            if rng.random() < 0.3:
                return 'D'
            return 'C'
        # Occasionally probe a very cooperative partner early, not near the end.
        if remaining > 12 and n > 3 and n % 11 == 0 and recent_rate >= 0.8:
            return 'D'
        return 'C'

    # Middle / mixed opponent: be cautiously reciprocal with forgiveness.
    if last_me == 'D':
        return 'C'
    if recent_rate >= 0.4:
        return 'C'
    if rng.random() < 0.2:
        return 'C'
    return 'D'
